def rotate_90(grid):
    """Rotate a 4x4 grid 90 degrees clockwise"""
    n = 4
    new_grid = [['.' for _ in range(n)] for _ in range(n)]
    for i in range(n):
        for j in range(n):
            new_grid[j][n-1-i] = grid[i][j]
    return new_grid

